// msfcore boot ROM: IMEM words 0..127 (128 x 16), registered read (same
// 1-cycle latency as the SRAM macro). Contents = tt_um_msf_bootrom_data.v,
// generated by `python test/assembler.py` from test/bootloader.s (boot
// protocol v2: framed UART / parallel loader with CRC-8 and ACK/NAK).
`default_nettype none

module tt_um_msf_bootrom (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [6:0] a,
    output wire [15:0] q
);
  reg [15:0] rom [0:127];
`include "tt_um_msf_bootrom_data.v"   // initial block: fills rom[0..127]
  // v3: the read register resets to word 0, so the decode stage has the first
  // instruction in the first cycle after reset while the core already fetches
  // word 1 (tt_um_msf_ctrl.v, imem_raddr). An asynchronous reset like every other
  // flop's: the fetch address never depends on rst_n combinationally.
  reg [15:0] q_r;
  always @(posedge clk or negedge rst_n)
    if (!rst_n) q_r <= ROM_W0;
    else        q_r <= rom[a];
  assign q = q_r;
endmodule
